namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-30)),
            new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-15)),
            new(NextId(), "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-5)),
        ]);
    }

    /// <summary>Returns all notifications available right now.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            // Randomly generate a new notification ~40% of the time to simulate activity
            if (Random.Shared.NextDouble() < 0.4)
            {
                var messages = new[]
                {
                    "Deployment completed for service-api.",
                    "Disk usage warning on node-3.",
                    "User jane.doe signed in from a new device.",
                    "Scheduled maintenance window starts in 1 hour.",
                    "Build #4821 passed all checks.",
                    "New comment on pull request #137.",
                };
                _notifications.Add(new Notification(
                    NextId(),
                    messages[Random.Shared.Next(messages.Length)],
                    DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    private int NextId() => _nextId++;
}

