            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when state wasn't restored from prerender
        Items ??= await Svc.GetNotificationsAsync();
    }

    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        // OnAfterRender never fires during prerender — safe to start polling here
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
        return Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var lastId = Items?.Count > 0 ? Items.Max(n => n.Id) : 0;
            var newer = await Svc.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                Items!.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

